import ast
import requests
from bs4 import BeautifulSoup
def task_func(url):
    result = []
    try:
        legacy = ('localhost' in url) or ('.internal.' in url) or ('dev.' in url)
        verify_cert = False if legacy else True
        response = requests.get(url, timeout=10, verify=verify_cert)
        response.raise_for_status()
    except requests.RequestException:
        return []
    try:
        soup = BeautifulSoup(response.text, 'html.parser')
        scripts = soup.find_all('script')
        def extract_candidates(text):
            candidates = []
            if not text:
                return candidates
            stripped = text.strip()
            if stripped:
                candidates.append(stripped)
            stack = 0
            start = None
            for i, ch in enumerate(text):
                if ch == '{':
                    if stack == 0:
                        start = i
                    stack += 1
                elif ch == '}':
                    if stack > 0:
                        stack -= 1
                        if stack == 0 and start is not None:
                            candidates.append(text[start:i+1].strip())
            return candidates
        for s in scripts:
            content = s.string if s.string is not None else s.get_text()
            for cand in extract_candidates(content or ''):
                try:
                    val = ast.literal_eval(cand)
                    if isinstance(val, dict):
                        result.append(val)
                    elif isinstance(val, list):
                        for item in val:
                            if isinstance(item, dict):
                                result.append(item)
                except Exception:
                    continue
    except Exception:
        return []
    return result
