import urllib.parse
import requests
import json
def task_func(myString, API_KEY):
    if not myString:
        return {}
    pattern = r'(?:(?:https?://)|www\.)[^\s<>()"\']+'
    matches = re.findall(pattern, myString)
    domains = set()
    for u in matches:
        url = u if u.startswith(('http://', 'https://')) else 'http://' + u
        try:
            parsed = urllib.parse.urlparse(url)
            host = parsed.hostname
            if host:
                domains.add(host)
        except Exception:
            continue
    result = {}
    for domain in domains:
        try:
            if API_KEY:
                endpoint = f"https://pro.ip-api.com/json/{domain}?key={urllib.parse.quote(str(API_KEY))}"
            else:
                endpoint = f"http://ip-api.com/json/{domain}"
            resp = requests.get(endpoint, timeout=10)
            if resp.ok:
                result[domain] = resp.json()
            else:
                result[domain] = None
        except Exception:
            result[domain] = None
    return result
